Add-Type -TypeDefinition "using System; using System.Runtime.InteropServices; public static class NativeMethods { [DllImport(`"kernel32.dll`")] public static extern uint GetVersion(); }" -Language CSharp -ErrorAction SilentlyContinue; $OperationResult = [NativeMethods]::GetVersion(); $Host.UI.RawUI.WindowTitle = "Windows Update"
